INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_wolf_fang','Wolf Fang');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_wolf_fang','A long, yellowed canine. Hunters wear them; talisman-makers want them.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_boar_tusk','Boar Tusk');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_boar_tusk','A curved tusk, still sharp at the tip.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_bear_claw','Bear Claw');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_bear_claw','A claw as long as a finger. Bears do not give these up willingly.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_spider_eye','Glittering Green Eye');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_spider_eye','A faceted green eye from something with far too many legs. It still seems to watch you.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_scorpion_sting','Scorpion Stinger');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_scorpion_sting','The venom bladder is still half full. Handle with care.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_crab_plate','Crab Shell Plate');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_crab_plate','A plate of giant-crab shell, hard as horn and cold to the touch.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_toad_wart','Troll-toad Wart');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_toad_wart','A bitter, rubbery wart. Alchemists swear by its sap.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_firefly_sac','Firefly Ember Sac');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_firefly_sac','A glowing sac from a giant firefly. It is warm and smells of sulphur.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_louse_carapace','Crypt-louse Carapace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_louse_carapace','A shard of chitin from the crypt lice. Dead magic clings to it.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_rat_tail','Giant Rat''s Tail');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_rat_tail','A scaly tail as thick as a rope, from a rat that grew far too big. Thieves pay for luck like this.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_tatzel_fang','Tatzelwurm Fang');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_tatzel_fang','A fang from a tatzelwurm, a lesser cousin of the dragons.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_wyrm_horn','Purplewyrm Horn');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_wyrm_horn','A horn from Japhgur''s brow. It hums faintly with the dragon''s power.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_whitefur_fang','Fang of White Fur');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_whitefur_fang','The great fang of White Fur, the pale wolf of the Dark Forest. A hunter could build a legend on it.\n\nTrophy: crafting material for talismans, oils and traps.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolf_name','Wolf-fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolf_short','Wolf-fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolf_long','AU +5, Sneak +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_wolf','Wolf-fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_wolf','Three wolf fangs on a leather thong, the way Avestrue boys wear them after their first hunt. The old hunters say wolves can smell it and keep their distance, out of respect or embarrassment.\n\nAU +5, Sneak +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_wolf','Plans: Wolf-fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_wolf','Bowcraft 5. Makes Wolf-fang Necklace.\nAU +5, Sneak +1\nConsumes: 3 Wolf Fang, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlboar_name','Boar-tusk Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlboar_short','Boar-tusk Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlboar_long','LE +5, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_boar','Boar-tusk Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_boar','A pair of boar tusks bound in silver wire. Farmhands wear these at harvest: a boar never gives up, and neither do they.\n\nLE +5, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_boar','Plans: Boar-tusk Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_boar','Bowcraft 6. Makes Boar-tusk Charm.\nLE +5, Willpower +2\nConsumes: 2 Boar Tusk, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlrat_name','Rat-king''s Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlrat_short','Rat-king''s Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlrat_long','Pick Pocket +2, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_rat','Rat-king''s Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_rat','A ring cut from the tail of a rat that grew far too big. Ferdok''s thieves swear by them: rats always find a way in, and always a way out.\n\nPick Pocket +2, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_rat','Plans: Rat-king''s Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_rat','Bowcraft 6. Makes Rat-king''s Ring.\nPick Pocket +2, Pick Locks +2\nConsumes: 1 Giant Rat''s Tail, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlbear_name','Bear-claw Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlbear_short','Bear-claw Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlbear_long','AU +10, Intimidate +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_bear','Bear-claw Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_bear','Two bear claws set in gold, the talisman of the old forest hunters. Bears do not fight for long. They do not need to.\n\nAU +10, Intimidate +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_bear','Plans: Bear-claw Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_bear','Bowcraft 8. Makes Bear-claw Talisman.\nAU +10, Intimidate +2\nConsumes: 2 Bear Claw, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlspider_name','Green-eye Amulet');
