INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlspider_long','Intuition +1; Immune to poison');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_spider','Green-eye Amulet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_spider','A glittering green eye from something with far too many legs, set in gold. It sees venom coming and tells the blood to ignore it.\n\nIntuition +1\nImmune to poison');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_spider','Plans: Green-eye Amulet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_spider','Bowcraft 10. Makes Green-eye Amulet.\nIntuition +1; Immune to poison\nConsumes: 1 Glittering Green Eye, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlscorpion_name','Scorpion-sting Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlscorpion_short','Scorpion-sting Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlscorpion_long','Dexterity +1, Attack +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_scorpion','Scorpion-sting Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_scorpion','A ring of scorpion stinger from the dwarves'' mushroom gardens, where the scorpions grow fat on the warmth. Quick as a sting, and just as sudden.\n\nDexterity +1, Attack +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_scorpion','Plans: Scorpion-sting Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_scorpion','Bowcraft 10. Makes Scorpion-sting Ring.\nDexterity +1, Attack +1\nConsumes: 2 Scorpion Stinger, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlfirefly_name','Ember-sac Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlfirefly_short','Ember-sac Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlfirefly_long','AE +5; Immune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_firefly','Ember-sac Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_firefly','A still-warm ember sac from a giant firefly, sealed in a gold locket. Fire does not bite the one who carries a piece of it.\n\nAE +5\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_firefly','Plans: Ember-sac Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_firefly','Bowcraft 10. Makes Ember-sac Charm.\nAE +5; Immune to burning\nConsumes: 2 Firefly Ember Sac, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTltatzel_name','Tatzelwurm-fang Amulet');
