INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTltatzel_long','Courage +2; Immune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_tatzel','Tatzelwurm-fang Amulet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_tatzel','A tatzelwurm fang bound in gold leaf. The beasts never back down from a fight, and neither does whoever wears this.\n\nCourage +2\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_tatzel','Plans: Tatzelwurm-fang Amulet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_tatzel','Bowcraft 12. Makes Tatzelwurm-fang Amulet.\nCourage +2; Immune to knockdown\nConsumes: 1 Tatzelwurm Fang, 2 Gold leaf, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwyrm_name','Purplewyrm-horn Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwyrm_short','Purplewyrm-horn Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwyrm_long','Strength +1, Constitution +1, Courage +1, LE +10; Immune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_wyrm','Purplewyrm-horn Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_wyrm','A horn from the brow of the great purple wyrm, bound in gold. Its strength hums in the chest like a second heartbeat.\n\nStrength +1, Constitution +1, Courage +1, LE +10\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_wyrm','Plans: Purplewyrm-horn Talisman');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_wyrm','Bowcraft 14. Makes Purplewyrm-horn Talisman.\nStrength +1, Constitution +1, Courage +1, LE +10; Immune to burning\nConsumes: 1 Purplewyrm Horn, 2 Gemstones, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolfalpha_name','Alpha''s Fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolfalpha_short','Alpha''s Fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolfalpha_long','Dodge +1, Sneak +2, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_wolf_alpha','Alpha''s Fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_wolf_alpha','A wolf-fang necklace rebuilt around the great fang of White Fur. You move like the pack leader now: low, quick, and never where the blow lands.\n\nDodge +1, Sneak +2, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_wolf_alpha','Plans: Alpha''s Fang Necklace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_wolf_alpha','Bowcraft 8. Makes Alpha''s Fang Necklace.\nDodge +1, Sneak +2, AU +5\nConsumes: 1 Wolf-fang Necklace, 1 Fang of White Fur, 2 Wolf Fang.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlward1_name','Warding Charm');
