INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlward1_long','Parry +1, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_ward1','Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_ward1','A disc of giant-crab shell on a leather thong, carried by Ferdok''s harbour men against bad luck. Blows and curses alike glance off it.
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_ward1','Plans: Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_ward1','Bowcraft 7. Makes Warding Charm.\nParry +1, Magic resistance +1\nConsumes: 2 Crab Shell Plate, 1 Leather strips.');
