INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlward2_short','Greater Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlward2_long','Parry +1, Magic resistance +2, Constitution +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_ward2','Greater Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_ward2','A crab-shell disc rubbed with bitter troll-toad sap by a Moorbridge druid. Spells slide off it like rain off a thatched roof.
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_ward2','Plans: Greater Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_ward2','Bowcraft 9. Makes Greater Warding Charm.\nParry +1, Magic resistance +2, Constitution +1\nConsumes: 1 Warding Charm, 2 Troll-toad Wart.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlward3_name','Grand Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlward3_short','Grand Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlward3_long','Parry +1, Magic resistance +3, Constitution +1, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_ward3','Grand Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_ward3','Crypt-louse chitin layered over shell and sap. It drinks dead magic and never seems to get full.
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_ward3','Plans: Grand Warding Charm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_ward3','Bowcraft 11. Makes Grand Warding Charm.\nParry +1, Magic resistance +3, Constitution +1, AU +5\nConsumes: 1 Greater Warding Charm, 2 Crypt-louse Carapace.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolf2_name','Moonhowl Pendant');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolf2_short','Moonhowl Pendant');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTlwolf2_long','AU +8, Sneak +2, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tl_wolf2','Moonhowl Pendant');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tl_wolf2','The wolf-fang necklace restrung on moon-mad sinew, with a fourth fang from Alvina''s wolves. Wolves hear it before they see you, and think twice.
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tl_wolf2','Plans: Moonhowl Pendant');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tl_wolf2','Bowcraft 9. Makes Moonhowl Pendant.\nAU +8, Sneak +2, Courage +1\nConsumes: 1 Wolf-fang Necklace, 1 Moon-mad Sinew, 2 Wolf Fang.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilfrost_short','Frostbite Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilfrost_long','On hit: +1 magic damage; 20% on hit: Cold Shock (Corpofrigo)');
