INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilfrost_long','On hit: +1 magic damage; 20% on hit: Cold Shock (Corpofrigo)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_oil_frost','Frostbite Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_oil_frost','A pale blue oil pressed from crab shell. The blade frosts over as it is applied, and so does whatever it cuts.\n\nCoats a weapon for 10 hits:\nOn hit: +1 magic damage\n20% on hit: Cold Shock (Corpofrigo)');
