INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_oil_frost','Alchemy 8. Makes 3 Frostbite Oil.\n10 hits: On hit: +1 magic damage; 20% on hit: Cold Shock (Corpofrigo)\nConsumes: 1 Crab Shell Plate, 1 Salve fat.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilember_short','Ember Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilember_long','On hit: +1 fire damage; 25% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilember_short','Ember Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilember_long','On hit: +1 fire damage; 25% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_oil_ember','Ember Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_oil_ember','Firefly sap stirred into fat: the blade smoulders for ten blows and leaves burns that will not close.\n\nCoats a weapon for 10 hits:\nOn hit: +1 fire damage\n25% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_oil_ember','Plans: Ember Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_oil_ember','Alchemy 8. Makes 3 Ember Oil.\n10 hits: On hit: +1 fire damage; 25% on hit: Burning\nConsumes: 1 Firefly Ember Sac, 1 Salve fat.');
