INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilvenom_long','25% on hit: Wyrm Venom');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilvenom_short','Spider Venom Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilvenom_long','25% on hit: Wyrm Venom');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_oil_venom','Spider Venom Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_oil_venom','Spider venom thickened with fat by Tallon''s herb-woman, who will not say who taught her.\n\nCoats a weapon for 10 hits:\n25% on hit: Wyrm Venom');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_oil_venom','Plans: Spider Venom Oil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_oil_venom','Alchemy 10. Makes 3 Spider Venom Oil.\n10 hits: 25% on hit: Wyrm Venom\nConsumes: 1 Glittering Green Eye, 1 Poison fang, 1 Salve fat.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilfrailty_short','Bonecrusher Paste');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilfrailty_long','20% on hit: Frailty');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilfrailty_short','Bonecrusher Paste');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilfrailty_long','20% on hit: Frailty');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_oil_frailty','Bonecrusher Paste');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_oil_frailty','Troll-toad sap that seeps into wounds and steals the strength from them. It smells worse than it works, which is saying something.\n\nCoats a weapon for 10 hits:\n20% on hit: Frailty');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_oil_frailty','Plans: Bonecrusher Paste');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_oil_frailty','Alchemy 9. Makes 3 Bonecrusher Paste.\n10 hits: 20% on hit: Frailty\nConsumes: 1 Troll-toad Wart, 1 Salve fat.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilholy_short','Holy Water of Praios');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_armoilholy_long','Against the undead: +1d6+2 magic damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('Weapon_add_armoilholy_short','Holy Water of Praios');
