INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetWyrm_name','Wyrm set: with the Wyrmscale Cuirass, Strength/Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGGloves_name','Plant Lore +2, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGGloves_short','Plant Lore +2, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGGloves_long','Plant Lore +2, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_gloves','Gatherer''s Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_gloves','Thin leather gloves stained green and red: herbs and hides.\n\nPlant Lore +2, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGGreenThumb_name','Plant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGGreenThumb_short','Plant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGGreenThumb_long','Plant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_green_thumb','Ring of the Green Thumb');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_green_thumb','A ring of twisted vine silver. Plants seem to lean towards it.\n\nPlant Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGHunterTotem_name','Animal Lore +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGHunterTotem_short','Animal Lore +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGHunterTotem_long','Animal Lore +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_hunter_totem','Hunter''s Totem');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_hunter_totem','A carved bone totem: the hunter, the herb-woman and the wanderer.\n\nAnimal Lore +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_skinner','Huntress'' Skinning Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_skinner','Owlstone keeps it sharp enough to split a hair.\n\nTool: put it in a quick slot and use it on a corpse: Animal Lore +2 for that check. Never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_sickle','Herbalist''s Sickle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_sickle','A small curved blade for cutting herbs at the root, the way Peraine teaches.\n\nTool: put it in a quick slot and use it on a plant: Plant Lore +2 for that check. Never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_master_furrier','Master Furrier''s Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_master_furrier','A furrier''s knife of fine Kosh steel. Every pelt, every claw comes off whole.\n\nTool: put it in a quick slot and use it on a corpse: Animal Lore +3 for that check. Never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_golden_sickle','Druid''s Golden Sickle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_golden_sickle','A golden sickle from the Moorbridge druids. It never wilts what it cuts.\n\nTool: put it in a quick slot and use it on a plant: Plant Lore +3 for that check. Never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_grand_furrier','Grandmaster Furrier''s Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_grand_furrier','A master furrier''s knife reforged with dwarven steel and a tatzelwurm fang. No hide is too tough, no claw too stubborn.\n\nTool: put it in a quick slot and use it on a corpse: Animal Lore +4 for that check. Never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_g_grand_furrier','Plans: Grandmaster Furrier''s Knife');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_g_grand_furrier','Smithing 12. Makes Grandmaster Furrier''s Knife.\nAnimal Lore +4 (tool). Upgrades Master Furrier''s Knife.\nConsumes: 1 Master Furrier''s Knife, 1 Tatzelwurm Fang, 1 Dwarven steel.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_g_harvest_sickle','Sickle of Peraine''s Harvest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_g_harvest_sickle','A druid''s golden sickle blessed with gold leaf and a living ember. Every herb it cuts yields a little more, as Peraine intended.\n\nTool: put it in a quick slot and use it on a plant: Plant Lore +4 for that check. Never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_g_harvest_sickle','Plans: Sickle of Peraine''s Harvest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_g_harvest_sickle','Alchemy 12. Makes Sickle of Peraine''s Harvest.\nPlant Lore +4 (tool). Upgrades Druid''s Golden Sickle.\nConsumes: 1 Druid''s Golden Sickle, 2 Gold leaf, 1 Gemstones, 1 Firefly Ember Sac.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmOmelette_name','Rakorium''s Omelette');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmOmelette_short','Rakorium''s Omelette');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmOmelette_long','Courage +3, Strength +1, Cleverness -1. You feel draconic. You are not.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgDranor_name','Haggle +2, Pick Pocket +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgDranor_short','Haggle +2, Pick Pocket +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgDranor_long','Haggle +2, Pick Pocket +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_dranor','Dranor''s Die-Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_dranor','A little ivory die on a short silver chain, fixed to a ring so Dranor can never lose it in a game again. He swears it is honest. It rolls a six suspiciously often.\n\nHaggle +2, Pick Pocket +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgKladdis_name','Seduce +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgKladdis_short','Seduce +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgKladdis_long','Seduce +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_kladdis','Kladdis''s Feather of Fortune');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_kladdis','A jay feather Kladdis wears for luck. She has never lost it, and never paid for it.\n\nSeduce +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgTraldar_name','Etiquette +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgTraldar_short','Etiquette +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgTraldar_long','Etiquette +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_traldar','Traldar''s Campaign Medal');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_traldar','From a war nobody in Ferdok remembers. Traldar remembers every name.\n\nEtiquette +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgNasreddin_name','Haggle +3, Fast Talk +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgNasreddin_short','Haggle +3, Fast Talk +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgNasreddin_long','Haggle +3, Fast Talk +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_nasreddin','Nasreddin''s Ring of a Hundred Prices');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_nasreddin','Engraved inside: ''Everything has a price. Mine is higher.''\n\nHaggle +3, Fast Talk +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAuralia_name','Alchemy +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAuralia_short','Alchemy +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAuralia_long','Alchemy +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_auralia','Auralia''s Pocket Alembic');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_auralia','A thumb-sized glass still on a chain. It bubbles when someone lies nearby.\n\nAlchemy +3, Plant Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAncoron_name','AE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAncoron_short','AE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgAncoron_long','AE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_ancoron','Ancoron''s Silver Leaf');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_ancoron','A leaf from the tree his family planted when he was born. It never wilts.\n\nAE +8, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgRhulana_name','Sabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgRhulana_short','Sabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmCgRhulana_long','Sabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_cg_rhulana','Kurkum Sister-Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_cg_rhulana','Every Amazon of Kurkum receives one when she swears to the Lioness. Inside, two names: Rhulana, and a second one scratched out until only an ''S'' remains. Rhulana will not say whose.\n\nSabers +1, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_rk_unmagical_hat','Rakorium''s Unmagical Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_rk_unmagical_hat','Not a speck of magic in it. Rakorium insists that is precisely its power. His second-best hat, he claims, is resting somewhere much further down the road, among the dead.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWantedPoster_name','Streetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWantedPoster_short','Streetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWantedPoster_long','Streetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_wanted_poster','Your Own Wanted Poster');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_wanted_poster','1000 ducats, dead or alive. The drawing looks nothing like you, which is exactly why you wear it, folded, over your heart.\n\nStreetwise +3, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWarpaint_name','Courage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWarpaint_short','Courage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXWarpaint_long','Courage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_warpaint','Pot of Kurkum Warpaint');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_warpaint','Rhulana''s spare warpaint, in a clay pot on a cord. Smells of iron and berries. Etiquette suffers; courage does not.\n\nCourage +1, Etiquette -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXJarNewt_name','AE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXJarNewt_short','AE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXJarNewt_long','AE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_jar_newt','Rakorium''s Pet ''Dragon''');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_jar_newt','A newt in a jar. Rakorium insists it breathed fire once. It has not breathed fire since. It is, however, very calm.\n\nAE +3, Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLoveLetters_name','Seduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLoveLetters_short','Seduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLoveLetters_long','Seduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_love_letters','Kladdis''s 37th Love Letter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_love_letters','Unsent, unsigned and wildly misspelled. Addressed to ''you know who you are''. Several people in Ferdok think it is about them.\n\nSeduce +2, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCyclopsMonocle_name','Perception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCyclopsMonocle_short','Perception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCyclopsMonocle_long','Perception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_cyclops_monocle','Cyclops Monocle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_cyclops_monocle','A lens the size of a plate, from a cyclops who needed reading glasses. Worn on a finger, you see everything, slightly enlarged.\n\nPerception +4, Agility -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLostBraid_name','Courage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLostBraid_short','Courage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXLostBraid_long','Courage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_lost_braid','Forgrimm''s Braid');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_lost_braid','The beard braid Forgrimm cut off in shame, as Ardo''s bodyguard. Ardo kept it, of course, in his chest of oddities, between the false beard and that shirt.\n\nCourage +1, Two-handed Axes/Maces +1, Charisma -1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBredoTab_name','Haggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBredoTab_short','Haggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBredoTab_long','Haggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_bredo_tab','Bredo''s Unpaid Tab');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_bredo_tab','A slate covered in chalk tallies of unpaid drinks. Some innkeeper carried it a long way rather than forgive a single one. Your name is at the top. Wearing it makes haggling feel like justice.\n\nHaggle +2, Willpower +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXTinyCrown_name','Charisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXTinyCrown_short','Charisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXTinyCrown_long','Charisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_tiny_crown','A Very Small Crown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_tiny_crown','Knowall insists it is the crown of a prince. It fits on a finger. It does not fit on a frog either.\n\nCharisma +1, Seduce +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_annoyance','Hammer of Mild Annoyance');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_annoyance','Forged by a smith who hated nobody in particular. It does not hurt much. It is just very, very annoying.\n\n30% on hit: Dazed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_tankard','Ferdok Tankard');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_tankard','A pewter tankard of the Silver Jug, reinforced for "discussions". Still half full.\n\n20% on hit: Stun\n25% on hit: heals the wielder 2 LE');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXArdoSock_name','Courage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXArdoSock_short','Courage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXArdoSock_long','Courage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_ardo_sock','Ardo''s Lucky Sock');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_ardo_sock','Ardo wore it at the Battle of Silkwiesen and never washed it again. On a string, round your neck. Bold.\n\nCourage +2, Charisma -2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCanoSignet_name','Etiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCanoSignet_short','Etiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXCanoSignet_long','Etiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_cano_signet','Cano''s Signet (Probably Stolen)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_cano_signet','Cano sold it to you for one ducat and a wink. The engraving belongs to a Horasian countess. Wear it and people bow to you, and every merchant doubles his prices for her ladyship. Do not wear it in Vinsalt.\n\nEtiquette +3, Charisma +1, Haggle -3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRakoriumHat_name','Cleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRakoriumHat_short','Cleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRakoriumHat_long','Cleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_rakorium_hat','Rakorium''s Second-Best Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_rakorium_hat','Smells of cave mould and dragon theories. Rakorium swears the best one was eaten by a dragon. Of course.\n\nCleverness +2, Intuition +1, Courage -1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRetreatBoots_name','Intuition +1, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRetreatBoots_short','Intuition +1, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXRetreatBoots_long','Intuition +1, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_retreat_boots','Boots of Strategic Retreat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_retreat_boots','They have never lost a battle. They have also never stayed for the end of one.\n\nIntuition +1, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBeardComb_name','Strength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBeardComb_short','Strength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXBeardComb_long','Strength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_beard_comb','Forgrimm''s Spare Beard Comb');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_beard_comb','A tiny silver comb on a ring. Forgrimm will deny ever owning it. Loudly. With an axe.\n\nStrength +1, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_dead_lockpick','Dead Man''s Lockpick');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_dead_lockpick','Wenzel''s lockpick, bent just so. He never needed it again. \n\nTool: put it in a quick slot and use it on a lock: Pick Locks +3 for that attempt. It never breaks and never needs to be equipped.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('name_arm_x_wenzel_note','Wenzel''s Last Note');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_wenzel_note','Wenzel''s Last Note');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('text_arm_x_wenzel_note','Whoever finds this: the Bald One said a cave this deep must hide a treasure. It hid a bear.\n\nMy share of the last job is hidden in the city, down where Phex''s children learn their trade. Seven is my lucky number. If the boss asks, the rat-tail sends his regards, and the boss still owes me three ducats.\n\n- Wenzel');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_lucky_arrow','Gwendala''s Lucky Arrow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_lucky_arrow','She says she has never missed with it. She has, twice. Do not mention it.\n\nOn hit: +15 damage\n50% on hit: Stun');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_dragon_egg','Totally Real Dragon Egg');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_dragon_egg','Rakorium insists it is a dragon egg. It is a chicken egg. Rakorium insists.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_golden_feather','Golden Feather');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_golden_feather','A feather of pure gold from an Avestrue chicken. Nobody can explain it. The chicken certainly could not.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_omelette','Rakorium''s Omelette');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_omelette','Made from a genuine dragon egg (chicken). Tastes of courage and slight regret.\n\nCourage +3, Strength +1, Cleverness -1 for 10 minutes.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_x_omelette','Plans: Rakorium''s Omelette');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_x_omelette','Alchemy 3. Makes Rakorium''s Omelette.\nCourage +3, Strength +1, Cleverness -1 for 10 minutes.\nConsumes: 1 Totally Real Dragon Egg, 1 Alcohol.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXGoldenHen_name','Dodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXGoldenHen_short','Dodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXGoldenHen_long','Dodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_golden_hen','Amulet of the Golden Hen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_golden_hen','The golden feather, set in gold. Enemies hesitate. Somewhere, a chicken clucks approvingly.\n\nDodge +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWarding_name','Armour +1 on every zone');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWarding_short','Armour +1 on every zone');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWarding_long','Armour +1 on every zone. Stacks with Armatrutz.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_warding','Ring of Warding');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_warding','A plain silver band, cold to the touch, with the Armatrutz glyph cut on the inside. Japhgur kept it with his gold: whoever wore it before him was very hard to kill, and still did not survive.\n\nArmour +1 on every zone. Stacks with Armatrutz.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXwarding2_name','Armour +2 on every zone, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXwarding2_short','Armour +2 on every zone, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXwarding2_long','Armour +2 on every zone, Magic resistance +1. Stacks with Armatrutz.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_warding2','Wyrmward Signet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_warding2','Reforged in Murolosh around a drop of the Purplewyrm''s blood. The glyph now runs all the way round the band, and spells slide off the wearer like rain off scales.\n\nArmour +2 on every zone, Magic resistance +1. Stacks with Armatrutz.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXwarding3_name','Armour +3 on every zone, Magic resistance +2, immune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXwarding3_short','Armour +3 on every zone, Magic resistance +2, immune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmXwarding3_long','Armour +3 on every zone, Magic resistance +2, immune to knockdown. Stacks with Armatrutz.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_warding3','Ward of the Old Bones');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_warding3','The cyclops of Gruldur was old when the dwarves were young, and the rune in its bones was older still. Set into the Wyrmward, it holds the wearer the way the mountain holds its roots.\n\nArmour +3 on every zone, Magic resistance +2, immune to knockdown. Stacks with Armatrutz.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_x_cyclops_bone','Cyclops Rune-Bone');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_x_cyclops_bone','A finger-bone of the cyclops of Gruldur, as long as a forearm, with one rune carved into it by no hand anyone remembers. Murolosh smiths will not touch it without a reason.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_x_warding2','Plans: Wyrmward Signet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_x_warding2','Smithing 13. Makes Wyrmward Signet.\nArmour +2 on every zone, Magic resistance +1.\nConsumes: 1 Ring of Warding, 2 Dragon blood, 1 Dwarven steel, 1 Gemstones.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_x_warding3','Plans: Ward of the Old Bones');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_x_warding3','Smithing 15. Makes Ward of the Old Bones.\nArmour +3 on every zone, Magic resistance +2, immune to knockdown.\nConsumes: 1 Wyrmward Signet, 1 Cyclops Rune-Bone, 2 Gold leaf.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_x_golden_hen','Plans: Amulet of the Golden Hen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_x_golden_hen','Bowcraft 6. Makes Amulet of the Golden Hen.\nAgility +1, Dodge +2, Courage +1\nConsumes: 1 Golden Feather, 1 Gold leaf.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoMut','\nThe magician calls for mystical aid from the astral plane in order to increase his or her Courage for a short time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoKlugheit','\nThe magician calls for mystical aid from the astral plane in order to increase his or her Cleverness for a short period of time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoIntuition','\nThe magician calls for mystical aid from the astral plane in order to increase his or her Intuition for a short period of time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoCharisma','\nThe magician calls for mystical aid from the astral plane in order to increase his or her Charisma for a short period of time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoFingerfertigkeit','\nThe magician calls for mystical aid from the astral plane in order to increase his or her Dexterity for a short period of time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoGewandtheit','\nThe magician calls for mystical aid from the astral plane in order to increase his Agility for a short period of time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoKonstitution','\nThe magician calls for mystical aid from the astral plane in order to increase his or her Constitution for a short period of time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAttributoKoerperkraft','\nThe magician calls for mystical aid from the astral plane in order to increase his or her Strength for a short period of time. It is possible to affect only one attribute per person. If a second one is cast, the first one will expire.\n\nEffect: Attribute +SP/3+1, always at full strength for the spell value (no bad rolls)\nSpell Duration: 1 hour\nCost: 7 AP\nModifier: No');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoOffensiverKampfstil2','A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat II will give your hero a bonus to its Attack Value (AV) sacrificing somewhat the defense. An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: AV +2\nEd Cost: 2 EP per attack in battle\nRequires: Base AV 8, Offensive
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoOffensiverKampfstil3','A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat III will give your hero a bonus to its Attack Value (AV) sacrificing somewhat the defense. An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: AV +4\nEd Cost: 3 EP per attack in battle\nRequires: Base AV 9, Offensive
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoDefensiverKampfstil2','Adopting this stance will enhance your hero''s abilities in defensive combat. Warriors selecting a defensive combat style receive a bonus to their Parry Value (PA) sacrificing somewhat the offense. The defensive combat style is strenuous and the defender will lose a number of endurance points per parry. It is not possible to select an offensive combat stance simultaneously.\n\nEffect: PA +2\nED Cost: 2 EP per parry in battle\nRequires: Base PA 7, Defensive
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoDefensiverKampfstil3','The Warrior is a master in the art of defensive combat. Warriors selecting a defensive combat style receive a bonus to their Parry Value (PA) sacrificing somewhat the offense. The defensive combat style is strenuous and the defender will lose a number of endurance points per parry. It is not possible to select an offensive combat stance simultaneously.\n\nEffect: PA +4\nED Cost: 3 EP per parry in battle\nRequires: Base PA 8, Defensive
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoGezielter Stich','The Lunge is a thrust directed at a vulnerable and preferably unprotected part of the opponent''s body. The only defense against a Lunge is to parry.\n\nEffect: Parry -4, ignore AR, +1 Wound\nED Cost: 15 EP\nRequires: SA Feint, CO 9, IN 12, AG 13');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoKlingensturm','This extremely aggressive combat technique allows the hero to carry out three consecutive strikes, only one of which can be parried (but they can miss). Skillful swordplay disorients the target, that exposes unprotected parts of the body while trying to defend, armor of the target is therefore halved.\n\nEffect: AR/2, 3 attacks\n\nED Cost: 20 EP\nRequires: SA Feint, CO 10, DE 12, IN 13');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoUmreissen','Rushing an opponent can force him to lose his balance. It does not cause any damage. The defender can use half of their Agility (AG) to prevent a fall.\n\nEffect: Test AG/2 or 2 CR thrown, this attack cannot be parried\nED Cost: 15 EP\nRequires: SA Feint, CO 11, IN 12, AG 11');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoTodesstoss','The Mortal Blow is a massive blow aimed at an unprotected part of the opponent''s body. The Mortal Blow is almost impossible to parry and causes massive damage. It is a strenuous attack and costs Endurance Points.\n\nEffect: Parry -6, DP x 2, ignore AR, +2 Wounds\nED Cost: 25 EP\nRequires: SA Lunge, CO 10, IN 15');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoNiederwerfen','This is an extremely powerful blow - its sheer force throws the opponent to the ground. The defender can test against half of its Strength (ST) to prevent a fall.\n\nEffect: Test ST/2 or 2 CR thrown\nED Cost: 10 EP\nRequires: SA Mighty Blow, ST 15, CO 13');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoBefreiungsschlag','The Roundhouse Blow is a defensive strike against multiple attackers.\n\nED Cost: 20 EP\nRequires: SA Mighty Blow, CO 13, AG 13');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoHammerschlag','The Strike of Wrath is the most powerful attack. It causes massive damage but requires considerable strength and endurance. Because of its power, the opponent will not parry the strike so easily.\n\nEffect: Parry -4, DP x 3, opponent must test ST or be knocked to the ground\nED Cost: 30 EP\nRequires: SA Knock Down, CO 15, CN 14');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoMeisterParade','This ability will allow the hero to focus on the next incoming attack with intense concentration. The concentration will cause some exhaustion, but the warrior will be successfully in the next dodge or parry maneuver.\n\nEffect: A Parry or Dodge maneuver will be succeed automatically during the next 15 combat rounds.\nED Cost: 8 EP\nRequires: Base PA 8');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoKlingenwand','The Wall of Blades is an advanced parrying technique enabling the hero to carry out an additional 5 parries over the next 15 combat rounds and defend himself against superior numbers.\n\nEffect: 5 extra parries over 15 CR\nED Cost: 15 EP\nRequires: SA Master Parry, AG 12');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoWindmuehle','This advanced fighting technique channels the force of an opponent''s blow back into a powerful counter-attack. The force of the opponent''s blade is absorbed and channeled back towards the opponent in one fluid and devastating movement.\n\nEffect: Three Parry and Dodge maneuvers will be successful for the next 15 combat rounds. The hero''s counter-attack cannot be parried.\nED Cost: 20 EP\nRequires: SA Wall of Blades, AG 12, IN 12');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoScharfschuetze','Marksman enables an archer to focus his attention on a target and to aim his shot at a vulnerable and unprotected part of the target''s body. Marksman ignores the target''s Armor Rating (AR) and automatically inflicts a wound.\n\nEffect: ignore AR, +1 Wound\nED Cost: 17 EP\nRequires: SA Aimed Shot, DE 12');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoMeisterschuetze','Master Marksman enables an archer to focus his entire attention on a target and to aim his shot at a vulnerable and unprotected part of the target''s body. Effect: 2x DP, ignore AR, +2 Wounds\nED Cost: 25 EP\nRequires: SA Marksman, DE 14');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoMeisterwurf','The Master Throw is an extremely powerful attack that inflicts severe damage, a nasty wound, ignores the opponent''s armor and will stun it (CN/2 to resist).\n\nEffect: 2 x DP, +1 Wound, Test CN/2 or stunned for 3 CR, ignore AR\nED Cost: 25 EP\nRequires: SA Power Throw, DE 13');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoEisenhagel','This attack enables the hero to cast up to four throwing knives at once towards a target. Success and the damage incurred is checked on a throw per throw basis. It cannot be performed with throwing axes.\n\nEffect: 4 throwing knife attacks with -8 PA, DP is calculated separately.\nED Cost: 15 EP\nRequires: SA Aimed Throw, DE 14');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoKraftwurf','The attacker aims very carefully and makes a strong and deadly throw that will throw the opponent to the ground if it is unable to prevent the fall with a test against half of their Strength (ST)\n\nEffect: 3 x DP, Test ST or knocked down for 1 CR.\nED Cost: 15 EP\nRequires: SA Aimed Throw, DE 11');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoPfeilhagel','This attack enables the archer to fire two arrows at a target at once. The accuracy of the shots is checked individually, as is the damage incurred.\n\nEffect: shoots 2 arrows, opponent penalized -4 to DV\nED Cost: 12 EP\nRequires: SA Aimed Shot, DE 14');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoLademeister','Thanks to his long years of experience the Master Crossbowman can reload a crossbow very quickly. This skill does not cost any Endurance Points and is permanently activated once purchased.\n\nEffect: Reloading a crossbow costs 1 CR less.\nED Cost: none\nRequires: SA Aimed Shot, Base RC 8');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAusdauernd2','Endurance is a crucial factor in battle. If a warrior''s Endurance reaches 0, he will be unable to perform any special attack. This passive special ability gives warriors a medium bonus to their maximum Endurance.\n\nEffect: +12 max. ED\nRequires: CN 13, SA Endurance I');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('InfoAusdauernd3','Endurance is a crucial factor in battle. If a warrior''s Endurance reaches 0, he will be unable to perform any special attack. This passive special ability gives warriors a large bonus to their maximum Endurance.\n\nEffect: +18 max. ED\nRequires: CN 14, SA Endurance I, SA Endurance II');
